<template><section><h2 class="text-2xl font-bold mb-6">Chi tiết Farm</h2><p v-if="error" class="text-error">{{error}}</p><p v-else-if="!farm" class="text-gray-400">Đang tải…</p><div v-else class="grid sm:grid-cols-2 gap-4"><div v-for="(value,key) in farm" :key="key" class="rounded bg-white/5 p-4"><p class="text-gray-400 text-sm">{{key}}</p><p>{{value}}</p></div></div></section></template><script setup>import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{adminApi}from'../../api/adminService';const route=useRoute(),farm=ref(null),error=ref('');onMounted(async()=>{try{farm.value=(await adminApi.farm(route.params.id)).data}catch(e){error.value=e.response?.data?.message||'Không thể tải Farm.'}})</script>
